  tool_emi_col_payment: 'Zahlung',
  tool_emi_col_period: 'Periode',
  tool_emi_col_principal: 'Tilgung',
  tool_emi_description:
    'Berechnen Sie die EMI-Rate aus Kreditsumme, Jahreszins und Laufzeit. Formel mit fallendem Saldo und Tilgungsplan. Optional Preis und Anzahlung; monatliche oder zweiwöchentliche Zahlung. Beispiel: 100.000 bei 6 % über 5 Jahre, monatlich → Rate ≈ 1.933,28. Berechnung im Browser; nur zu Lernzwecken, keine Kreditberatung.',
  tool_emi_disclaimer:
    'EMI- und Tilgungsergebnisse sind nur Lernillustrationen und keine Kredit-, Hypotheken-, Steuer- oder Finanzberatung. Reale Kredite können Gebühren, Versicherungen und Steuern enthalten, die hier nicht modelliert sind.',
  tool_emi_down_label: 'Anzahlung',
  tool_emi_down_placeholder: 'z. B. 20000',
  tool_emi_err_overflow: 'Ergebnis ist nicht endlich. Zins und Laufzeit prüfen.',
  tool_emi_err_periods: 'Ungültige Zahlungsanzahl. Laufzeit und Häufigkeit prüfen.',
