  tool_measuring_magnetic_fields_chart_earth: 'Erdmagnetfeld (Kontrolle schwacher Felder)',
  tool_measuring_magnetic_fields_chart_earth_b: '~25–65 µT (hier ~50 µT als Mitte)',
